import os
import json
import hashlib
import hmac
import tempfile
import time
import stat
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

SESSION_DIR = '/var/lib/app/sessions'


def _load_secret_key() -> bytes:
    """Load the application secret key, refusing to start if it is missing or weak."""
    raw = os.environ.get('APP_SECRET_KEY', '')
    key = raw.encode('utf-8')
    if len(key) < 32:
        raise RuntimeError(
            'APP_SECRET_KEY is not set or too short; a secret key of at least '
            '32 bytes is required for secure session MACs.'
        )
    return key


SECRET_KEY = _load_secret_key()
ADMIN_TOKEN_FILE = '/etc/app/admin_token'

def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)

def sanitize_session_id(session_id: str) -> str:
    """Sanitize session ID to prevent path traversal."""
    # Only allow alphanumeric and hyphens
    cleaned = ''.join(c for c in session_id if c.isalnum() or c == '-')
    if len(cleaned) < 8 or len(cleaned) > 64:
        return ''
    return cleaned

def compute_session_mac(session_id: str, data: bytes) -> str:
    """Compute HMAC for session integrity verification."""
    mac = hmac.new(SECRET_KEY, session_id.encode() + data, hashlib.sha256)
    return mac.hexdigest()

def read_session(session_id: str) -> dict:
    """Read and validate a session from the session store.
    Uses O_NOFOLLOW to atomically reject symlinks at open time,
    preventing TOCTOU race conditions."""
    clean_id = sanitize_session_id(session_id)
    if not clean_id:
        return None

    session_path = os.path.join(SESSION_DIR, clean_id + '.json')

    # Open with O_NOFOLLOW to atomically reject symlinks
    # This prevents TOCTOU between check and open
    try:
        fd = os.open(session_path, os.O_RDONLY | os.O_NOFOLLOW)
    except OSError:
        return None

    try:
        # Verify file metadata using the file descriptor (not path)
        # This is race-free since we operate on the opened fd
        fd_stat = os.fstat(fd)
        if fd_stat.st_uid != os.getuid():
            return None
        if fd_stat.st_mode & 0o077 != 0:
            return None
        if not stat.S_ISREG(fd_stat.st_mode):
            return None

        # Read from the already-opened file descriptor
        data = os.read(fd, 8192).decode('utf-8')
    except (OSError, UnicodeDecodeError):
        return None
    finally:
        os.close(fd)

    try:
        session = json.loads(data)
    except json.JSONDecodeError:
        return None

    # Verify session MAC integrity
    stored_mac = session.get('_mac', '')
    session_data = {k: v for k, v in session.items() if k != '_mac'}
    expected_mac = compute_session_mac(clean_id, json.dumps(session_data, sort_keys=True).encode())

    if not constant_time_compare(stored_mac.encode(), expected_mac.encode()):
        return None

    # Check expiration
    if session.get('expires_at', 0) < time.time():
        return None

    return session_data

def write_session(session_id: str, data: dict) -> bool:
    """Write a session to the session store with MAC protection."""
    clean_id = sanitize_session_id(session_id)
    if not clean_id:
        return False

    session_path = os.path.join(SESSION_DIR, clean_id + '.json')
    session_data = dict(data)
    session_data['expires_at'] = time.time() + 3600
    mac = compute_session_mac(clean_id, json.dumps(session_data, sort_keys=True).encode())
    session_data['_mac'] = mac

    # Write atomically using temp file + rename
    fd, tmp_path = tempfile.mkstemp(dir=SESSION_DIR, suffix='.tmp')
    try:
        os.write(fd, json.dumps(session_data).encode())
        os.fchmod(fd, 0o600)
        os.close(fd)
        os.rename(tmp_path, session_path)
    except OSError:
        try:
            os.close(fd)
        except OSError:
            pass
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        return False
    return True

class AppHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass  # Suppress logging to prevent info disclosure

    def do_GET(self):
        parsed = urlparse(self.path)

        if parsed.path == '/api/profile':
            self.handle_profile()
        elif parsed.path == '/api/admin/config':
            self.handle_admin_config()
        else:
            self.send_error(404)

    def get_session(self):
        cookie_header = self.headers.get('Cookie', '')
        for part in cookie_header.split(';'):
            part = part.strip()
            if part.startswith('sid='):
                return read_session(part[4:])
        return None

    def handle_profile(self):
        session = self.get_session()
        if not session:
            self.send_error(401, 'Unauthorized')
            return
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        safe_data = {'username': session.get('username', ''), 'role': session.get('role', 'user')}
        self.wfile.write(json.dumps(safe_data).encode())

    def handle_admin_config(self):
        session = self.get_session()
        if not session or session.get('role') != 'admin':
            self.send_error(403, 'Forbidden')
            return
        # Return non-sensitive operational config only
        config = {
            'session_count': len(os.listdir(SESSION_DIR)) if os.path.isdir(SESSION_DIR) else 0,
            'server_time': time.time()
        }
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(config).encode())

if __name__ == '__main__':
    os.makedirs(SESSION_DIR, mode=0o700, exist_ok=True)
    server = HTTPServer(('127.0.0.1', 8080), AppHandler)
    server.serve_forever()
